  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Accidents hémorragiques dus à un état fibrinolytique primitif généralisé.', 'Accidents hémorragiques au cours d''un traitement à effet fibrinolytique.', 'Accidents hémorragiques entretenus par une fibrinolyse locale, comme c''est le cas dans :', 'o ménorragies et métrorragies :', '§ par dysfonctionnement hormonal,', '§ secondaires à des lésions traumatiques ou infectieuses, ou dégénératives de l''utérus.', 'o hémorragies digestives,', 'o hématuries d''origine basse :', '§ des adénomes prostatiques,', '§ des néoplasies malignes prostatiques et vésicales,', '§ des lithiases,', '§ et plus généralement des affections urinaires hémorragiques, au décours des interventions chirurgicales prostatiques et des actes chirurgicaux intéressant le tractus urinaire.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Thrombose veineuse ou artérielle aiguë (voir rubrique 4.4).', 'Etats fibrinolytiques réactionnels à une coagulopathie de consommation, à l''exception d''états associés à une activation prédominante du système fibrinolytique avec une hémorragie grave aigüe (voir rubrique 4.4).', 'Insuffisance rénale grave (risque d''accumulation).', 'Antécédent de convulsions.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Evénements thrombo-emboliques', 'Les facteurs de risque de maladie thrombo-embolique doivent être pris en compte avant l’utilisation d’acide tranexamique.', 'Oestro-progestatifs', 'L’acide tranexamique doit être administré avec prudence chez les patientes sous oestro-progestatifs (contraception orale et hormonothérapie substitutive) du fait du risque accru de thrombose (voir rubrique 4.5).', 'Le traitement doit être arrêté immédiatement en cas de survenue de troubles thromboemboliques artériels ou veineux.', 'Troubles visuels', 'Il faut prêter attention aux troubles visuels possibles, notamment une déficience visuelle, une vision trouble, une perturbation de la vision des couleurs.', 'Si nécessaire, le traitement doit être interrompu.', 'Précautions d''emploi', 'Convulsions', 'Des cas de convulsions ont été rapportés en association avec un traitement par l’acide tranexamique.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune étude d’interaction n’a été réalisée.', 'Un traitement simultané par des anticoagulants doit être administré sous la stricte surveillance d’un médecin spécialisé dans ce domaine.', 'Les médicaments qui agissent sur l’hémostase doivent être administrés avec précaution aux patients traités par l’acide tranexamique.', 'Par ailleurs, l’effet antifibrinolytique du médicament peut être antagonisé avec des thrombolytiques.', 'Il existe un risque théorique d’augmentation de la formation de thrombus, tel qu’avec les œstrogènes.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences ont été définies comme suit : très fréquent (≥1/10) ; fréquent (≥1/100 à', 'Fréquent']);
