  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Nettoyage de la peu érodée et des petites plaies.', 'Petites hémorragies capillaires par plaies superficielles.', 'Remarque : les agents à visée antiseptique ne sont pas stérilisants, ils réduisent temporairement sur la peau et les muqueuses le nombre des micro-organismes.']);
