  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mise en garde', 'Dès l’ouverture du conditionnement d’une préparation à visée antiseptique, une contamination microbienne est possible.', 'Ne pas utiliser pour l’irrigation des cavités closes ou semi-closes ni sur des plaies très vascularisées, ou sous pansement occlusif.', 'Des embolies gazeuses d’évolution fatale, par formation et diffusion de bulles d’O2, ont été rapportées à cette utilisation pour des doses parfois minimes.', 'Ce produit doit être utilisé dans le strict respect de ses indications.', 'Précautions d’emploi', 'Ne pas avaler', 'Ne pas injecter']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Compte tenu des interférences possibles (antagonisme, inactivation) l''emploi simultané ou successif d''antiseptiques est à éviter.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables rapportés avec Eau oxygénée Gifrer 10 volumes sont répertoriés ci-dessous par Système Organe Classe.', 'Affections vasculaires', 'Des cas d’embolie gazeuse d’évolution parfois fatale ont été rapportés.', 'Troubles généraux et anomalies au site d’administration', 'Sensations de picotements sur les plaies.', 'Déclaration des effets indésirables suspectés']);
  -- trinitrine (CIS 60703590, scored)
