  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être prescrit dans les cas suivants :', 'hypotension marquée avec état de choc.', 'association aux inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil) (voir rubriques 4.5 et 4.4) :', 'o chez tout patient traité par la molsidomine on ne doit pas prescrire d’inhibiteurs de la phosphodiestérase de type 5 tant que le patient est sous l''action de la molsidomine.', 'o En cas de traitement par les inhibiteurs de la phosphodiestérase de type 5, la molsidomine est contre-indiquée.', 'hypersensibilité à la molsidomine ou à l’un des excipients.', 'Ce médicament est généralement déconseillé en cas d''allaitement (voir rubrique 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Association de la molsidomine aux inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil) :', 'Excipients', 'Ce médicament contient du lactose.', 'Son utilisation est déconseillée chez les patients présentant une intolérance au galactose, un déficit en lactase de Lapp ou un syndrome de malabsorption du glucose ou du galactose (maladies héréditaires rares).', 'Précautions d''emploi', 'Une légère baisse de la pression artérielle est habituelle sous molsidomine.', 'Une posologie progressive est recommandée en cas d''insuffisance hépatocellulaire.', 'Dénuée de tout effet dépresseur myocardique, la molsidomine peut être associée aux bêta-bloquants.', 'Elle est dépourvue d''effet sur le tissu de conduction.', 'La substitution aux dérivés nitrés retard est plus logique que l''association, en raison d''une action commune sur la précharge.', 'Il n''est pas logique d''associer la molsidomine avec les dérivés nitrés d''action prolongée dans la mesure où leur mécanisme d''action est similaire.', 'Alcaloïdes de l’ergot de seigle : Une interaction pharmacodynamique (effet antagoniste), entre les donneurs de monoxyde d’azote (NO) et les alcaloïdes de l’ergot de seigle est possible.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', '+ Inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil).', 'Risque d''hypotension importante (effet synergique) pouvant aggraver l''état d''ischémie myocardique et provoquer notamment un accident coronarien aigu.', '+ Riociguat', 'Risque d’hypotension importante (effet synergique)', 'Associations faisant l''objet de précautions d’emploi', 'En effet, les effets hypotensifs peuvent être majorés.', 'Associations à prendre en compte', '+ Dapoxétine', 'Risque de majoration des effets indésirables, notamment à type de vertiges ou de syncopes.', '+ Médicaments abaissant la pression artérielle', 'Majoration du risque d’hypotension, notamment orthostatique.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Des céphalées habituellement modérées et une légère baisse tensionnelle peuvent apparaître en début de traitement.', 'Les céphalées régressent en général spontanément en quelques jours.', 'Ces effets peuvent être majorés par la prise simultanée d''autres vasodilatateurs.', 'Une posologie progressive permet d''en réduire la fréquence.', 'Exceptionnellement, ont été signalés une hypotension orthostatique, des troubles digestifs, des vertiges ou un prurit.', 'De rares cas de thrombopénie ont été rapportés.']);
