  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['L’amlodipine est contre-indiquée chez les patients présentant :', 'une hypersensibilité à l’amlodipine, aux dérivés de la dihydropyridine ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'une hypotension sévère ;', 'un choc (y compris choc cardiogénique) ;', 'une obstruction de la voie d’éjection du ventricule gauche (par exemple, sténose aortique de degré élevé) ;', 'une insuffisance cardiaque hémodynamiquement instable après un infarctus aigu du myocarde.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['La sécurité d’emploi et l’efficacité de l’amlodipine au cours d’une crise hypertensive n’ont pas été établies.', 'Patients atteints d’insuffisance cardiaque', 'Les patients atteints d’insuffisance cardiaque doivent être traités avec précaution.', 'Patients atteints d’insuffisance hépatique', 'La demi-vie de l’amlodipine est augmentée et son ASC (Aire Sous la Courbe) est plus grande chez les patients atteints d’insuffisance hépatique ; les recommandations posologiques n’ont pas été établies.', 'Par conséquent l’amlodipine devra être initiée à la dose efficace la plus faible et avec précaution, aussi bien durant l’initiation du traitement que lors de l’augmentation de la dose.', 'Une augmentation posologique lente et une surveillance attentive peuvent être nécessaires chez les patients avec une insuffisance hépatique sévère.', 'Patients âgés', 'Chez les sujets âgés, une augmentation de la posologie doit être effectuée avec précaution (voir rubriques 4.2 et 5.2).', 'Patients atteints d’insuffisance rénale', 'L’amlodipine peut être utilisée chez ces patients à des doses normales.', 'Les changements des concentrations plasmatiques d’amlodipine ne sont pas corrélés avec le degré d’insuffisance rénale.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Effets des autres médicaments sur l’amlodipine', '+ Inhibiteurs du CYP3A4', 'La traduction clinique de ces variations pharmacocinétiques peut être plus prononcée chez le sujet âgé.', 'Par conséquent, une surveillance clinique et un ajustement de la dose pourront être nécessaires.', '+ Inducteurs du CYP3A4', 'Lors de la co-administration d’inducteurs connus du CYP3A4, la concentration plasmatique d’amlodipine peut varier.', '+ Dantrolène (perfusion)', 'Chez l’animal, une fibrillation ventriculaire et un collapsus cardiovasculaire létaux ont été observés en association avec une hyperkaliémie après l’administration de vérapamil et de dantrolène IV.', 'Effets de l’amlodipine sur d’autres médicaments', 'Les effets hypotenseurs de l’amlodipine s’ajoutent à ceux d’autres médicaments présentant des propriétés antihypertensives.', '+ Tacrolimus', '+ Inhibiteurs de la cible mécanique de la rapamycine (mTOR)']);
