  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['LERCANIDIPINE ACCORD est indiqué dans le traitement de l''hypertension essentielle légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Obstacle à l’éjection du ventricule gauche.', 'Insuffisance cardiaque congestive non traitée.', 'Angor instable ou infarctus du myocarde datant de moins d’un mois.', 'Insuffisance hépatique sévère.', 'Insuffisance rénale sévère (DFG', 'En association avec :', 'o inhibiteurs puissants du CYP3A4 (voir rubrique 4.5) ;', 'o ciclosporine (voir rubrique 4.5) ;', 'o pamplemousse ou jus de pamplemousse (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Maladie sinusale', 'La lercanidipine doit être administrée avec prudence chez les patients présentant une dysfonction du nœud sinusal (lorsqu’un stimulateur cardiaque n’a pas été installé).', 'Dysfonction ventriculaire gauche', 'Même si des études hémodynamiques contrôlées n’ont révélé aucune altération de la fonction ventriculaire, des précautions doivent être prises chez des patients ayant une dysfonction ventriculaire gauche.', 'Cardiopathie ischémique', 'Les données suggèrent que les patients atteints de cardiopathie ischémique présentent un risque cardiovasculaire élevé sous traitement par certaines dihydropyridines à courte durée d’action.', 'Bien que la lercanidipine possède une longue durée d’action, la prudence est recommandée chez ces patients.', 'Dans de rares cas, certaines dihydropyridines peuvent entraîner des douleurs précordiales ou un angor.', 'Dans de très rares cas, des patients ayant un angor préexistant peuvent présenter une augmentation de la fréquence, de la durée ou de la gravité des crises angineuses.', 'Des cas isolés d’infarctus du myocarde peuvent être observés (voir rubrique 4.8).', 'Utilisation en cas d''insuffisance rénale ou hépatique', 'Une prudence particulière doit être exercée au début du traitement chez les patients présentant une insuffisance rénale légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Inhibiteurs du cytochrome CYP3A4', 'La lercanidipine est métabolisée par l’enzyme CYP3A4 et, par conséquent, les inhibiteurs du cytochrome CYP3A4 administrés simultanément peuvent interagir avec le métabolisme et l’élimination de la lercanidipine.', 'L’administration de lercanidipine avec des inhibiteurs du CYP3A4 (par exemple kétoconazole, itraconazole, ritonavir, érythromycine, troléandomycine, clarithromycine) doit être évitée (voir rubrique 4.3).', 'Ciclosporine', 'Une élévation des concentrations plasmatiques de lercanidipine et de ciclosporine a été observée après administration concomitante des 2 principes actifs.', 'Cependant, l''administration concomitante de lercanidipine et de ciclosporine a provoqué une augmentation de 3 fois les concentrations plasmatiques de lercanidipine et une augmentation de 21% de l''ASC de la ciclosporine.', 'La ciclosporine et la lercanidipine ne doivent pas être administrées ensemble (voir rubrique 4.3).', 'Jus de pamplemousse ou de pamplemousse', 'La lercanidipine ne doit pas être prise avec du pamplemousse ou du jus de pamplemousse (voir rubrique 4.3).', 'Associations déconseillées', 'Inducteurs du cytochrome CYP3A4']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent', 'Peu fréquent']);
